message.content:
{
  "gate_token": "xIBn1hjWBtYnwcsAaTJV9Q",
  "title": "The Mirror Road Out",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept ridge at dusk, broken spires on the horizon, a parchment map weighted with stones and a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false invitations ahead.",
      "visual_description": "Close-up of an oil lamp held aloft, a single bright eye flickering inside the flame, its glow lighting Mara's worried face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the cracked castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes crouched under a massive iron portcullis, key-wind tail ticking quietly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass diver arrives by stepping out of a shattered window.",
      "visual_description": "A figure in a clear diving helmet emerging from a tall broken window, coat shimmering with reflections of burning lanterns.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They ignore the rumor of a beast circling the cursed tower.",
      "visual_description": "A leaning black tower wrapped in smoke against a red moon; the team passes below, refusing to look up.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Old royal banners flap above empty streets.",
      "visual_description": "Tattered gold-and-blue banners hanging from balconies over cobblestones strewn with debris, the tin fox trotting between puddles.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol marches past their hiding place.",
      "visual_description": "Shadowed alcove behind a fountain; mirrored helms and pikes glint as a column tramps by, the lamp's eye squeezed shut.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Frightened townsfolk peek from shuttered windows.",
      "visual_description": "Narrow lane lined with shutters cracked open, pale faces and candle stubs visible inside; the tin fox raises a paw in silent greeting.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "They find the sleeping tax collector blocking the records hall.",
      "visual_description": "A round official slumped at a desk in a marble hall, ledger as pillow, stamped papers stuck to his sleeves and cheek.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara copies a hidden map from beneath his elbow.",
      "visual_description": "Mara carefully sliding a yellowed chart from under the snoring official's arm, her compass swinging, ink smudging her cuff.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp reveals a magic door behind a tapestry.",
      "visual_description": "A dusty tapestry pulled aside to show a stone arch glowing with silver runes, lamp-light reflected in the carvings.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Glass diver dives headfirst into the door's mirrored surface.",
      "visual_description": "The diver plunging through a rippling silver pane like water, coat trailing fractured light, tin fox watching from the floor.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Inside the mirror tunnel, the captive is found chained to a chair.",
      "visual_description": "A long corridor of facing mirrors with a small figure tied in the center, infinite reflections of the diver approaching with bolt cutters.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The tin fox triggers an alarm chime to lure the patrol away.",
      "visual_description": "Clockwork fox leaping from a bell rope as bronze bells swing; armored figures sprint past in the background, oblivious.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Mara plots the fastest route to the river bridge.",
      "visual_description": "Mara crouched on rubble with two maps overlapping, compass needle spinning, lamp held close to read the lines.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Glass diver carries the rescued captive out through a shop window.",
      "visual_description": "A storefront pane rippling outward as the diver steps through cradling a cloaked figure, glass shards hanging frozen in midair.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the long stone bridge at dawn.",
      "visual_description": "A cracked arched bridge over dark water, sunrise behind ruined towers, the team running with banners snapping overhead.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the lamp's eye finally closes.",
      "visual_description": "A grassy bank at sunrise, the city smoking behind them; Mara folding her map, tin fox curled at her boot, lamp flame dimming to a peaceful glow.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

